package facetec

import (
	"encoding/base64"
	"testing"
)

// iso19794DG2Base64 is a real, standard ICAO 9303/19794-5 EF.DG2 file
// (BER-TLV, application tag 0x75), base64-encoded to match the shape
// FaceTec Server returns under documentData.nfcValues.rawData.DG2. This is
// a public conformance test vector reused verbatim from gmrtd's own test
// suite (github.com/gmrtd/gmrtd document/dg2_test.go, TestNewDG2Iso19794,
// MIT licensed) — not anyone's real biometric data.
const iso19794DG2Base64 = ""

// iso19794FaceImageBase64 is the JPEG face image embedded in
// iso19794DG2Base64, base64-encoded. This is what extractPortraitFromDG2 is
// expected to produce as documentData.Portrait.
const iso19794FaceImageBase64 = ""

func TestExtractPortraitFromDG2_Valid(t *testing.T) {
	documentData := map[string]any{
		"nfcValues": map[string]any{
			"rawData": map[string]any{
				"DG2": iso19794DG2Base64,
			},
		},
	}
	got := extractPortraitFromDG2(documentData)
	if got != iso19794FaceImageBase64 {
		t.Errorf("extractPortraitFromDG2: got %d base64 chars, want %d (content mismatch)", len(got), len(iso19794FaceImageBase64))
	}
}

func TestExtractPortraitFromDG2_NoNFCValues(t *testing.T) {
	documentData := map[string]any{}
	if got := extractPortraitFromDG2(documentData); got != "" {
		t.Errorf("got %q, want empty when nfcValues is absent", got)
	}
}

func TestExtractPortraitFromDG2_NoRawData(t *testing.T) {
	documentData := map[string]any{
		"nfcValues": map[string]any{
			"extractedInfo": map[string]any{"firstName": "JESSE"},
		},
	}
	if got := extractPortraitFromDG2(documentData); got != "" {
		t.Errorf("got %q, want empty when rawData is absent", got)
	}
}

func TestExtractPortraitFromDG2_NoDG2Key(t *testing.T) {
	documentData := map[string]any{
		"nfcValues": map[string]any{
			"rawData": map[string]any{
				"DG1": "c29tZS1kZzE=",
			},
		},
	}
	if got := extractPortraitFromDG2(documentData); got != "" {
		t.Errorf("got %q, want empty when DG2 key is absent", got)
	}
}

func TestExtractPortraitFromDG2_InvalidBase64(t *testing.T) {
	documentData := map[string]any{
		"nfcValues": map[string]any{
			"rawData": map[string]any{
				"DG2": "not-valid-base64!!!",
			},
		},
	}
	if got := extractPortraitFromDG2(documentData); got != "" {
		t.Errorf("got %q, want empty for invalid base64", got)
	}
}

func TestExtractPortraitFromDG2_InvalidTLV(t *testing.T) {
	// Valid base64, but not a valid EF.DG2 BER-TLV structure (missing the
	// 0x75 application tag entirely).
	documentData := map[string]any{
		"nfcValues": map[string]any{
			"rawData": map[string]any{
				"DG2": base64.StdEncoding.EncodeToString([]byte{0x01, 0x02, 0x12, 0x34}),
			},
		},
	}
	if got := extractPortraitFromDG2(documentData); got != "" {
		t.Errorf("got %q, want empty for malformed DG2 TLV", got)
	}
}

// TestExtractScanResult_PortraitFromNFCDG2 verifies the full ExtractScanResult
// path: an NFC-read passport (documentData.nfcValues.rawData.DG2 present,
// no photoIDFaceCrop anywhere) still yields a portrait, extracted from the
// chip's DG2 face image. This is the real-world shape confirmed against a
// live FaceTec Server v10 response — photoIDFaceCrop is not present at all
// in this deployment; DG2 is the only source of a portrait.
func TestExtractScanResult_PortraitFromNFCDG2(t *testing.T) {
	p := realPayload()
	results := p["idScanResultsSoFar"].(map[string]any)
	docData := map[string]any{
		"mrzValues":     map[string]any{"groups": []any{}},
		"scannedValues": map[string]any{"groups": []any{}},
		"templateInfo":  map[string]any{"templateType": "Passport"},
		"nfcValues": map[string]any{
			"rawData": map[string]any{
				"DG2": iso19794DG2Base64,
			},
		},
	}
	results["documentData"] = docData
	result, ok, err := ExtractScanResult(p)
	if err != nil || !ok {
		t.Fatalf("err=%v ok=%v", err, ok)
	}
	if result.IDScan.DocumentData.Portrait != iso19794FaceImageBase64 {
		t.Errorf("Portrait: got %d base64 chars, want %d (content mismatch)", len(result.IDScan.DocumentData.Portrait), len(iso19794FaceImageBase64))
	}
}

// TestExtractScanResult_PhotoIDFaceCropTakesPrecedenceOverDG2 documents the
// precedence rule when both sources are present: a directly-provided
// photoIDFaceCrop (already cropped/normalized by FaceTec) wins over the
// NFC-derived DG2 image.
func TestExtractScanResult_PhotoIDFaceCropTakesPrecedenceOverDG2(t *testing.T) {
	p := realPayload()
	results := p["idScanResultsSoFar"].(map[string]any)
	docData := map[string]any{
		"mrzValues": map[string]any{"groups": []any{}},
		"nfcValues": map[string]any{
			"rawData": map[string]any{
				"DG2": iso19794DG2Base64,
			},
		},
	}
	results["documentData"] = docData
	results["photoIDFaceCrop"] = "pre-cropped-photo"
	result, ok, err := ExtractScanResult(p)
	if err != nil || !ok {
		t.Fatalf("err=%v ok=%v", err, ok)
	}
	if result.IDScan.DocumentData.Portrait != "pre-cropped-photo" {
		t.Errorf("Portrait: got %q, want pre-cropped-photo (photoIDFaceCrop should win)", result.IDScan.DocumentData.Portrait)
	}
}
